        is AcmeRadius.Fixed -> radius.value.toPx() + out
        AcmeRadius.Full -> minOf(size.width, size.height) / 2 + out
        null -> 0f
    }
    drawRoundRect(
        color,
        topLeft = Offset(-out, -out),
        size = size.copy(width = size.width + 2 * out, height = size.height + 2 * out),
        cornerRadius = CornerRadius(corner),
        style = Stroke(w),
